import { useMemo } from 'react';
import { useLoader } from '@react-three/fiber';
import * as THREE from 'three/webgpu';

import grassPlacementUrl from '#assets/textures/grass-placement.png';
import { mulberry32 } from '#utils/random.js';

// Blades are spawned only where the placement mask says there is grass. The
// mask is a 128x128 CPU-readable copy of the height map (the KTX2 the shader
// samples cannot be read back), regenerated by scripts/pack-textures.mjs.
// The old hashed placement covered the whole square patch and the vertex
// shader collapsed ~73% of the blades every frame after doing all the work.
//
// Threshold sits under the shader's 0.25 collapse so mask edges never clip
// blades the full-res height texture would keep; the shader still collapses
// the few that land outside.
const PLACEMENT_THRESHOLD = 0.2 * 255;

// Instances are ordered by grid cell so consecutive instance IDs are
// neighbours in the patch: the per-instance culls in the vertex shader (view
// cone, distance thinning) then agree across whole GPU warps instead of
// diverging on every blade
const SORT_GRID = 32;

// Fixed seed: identical layout on every load
const SEED = 0x9e3779b9;

const readMask = image => {
  const canvas = document.createElement('canvas');
  canvas.width = image.width;
  canvas.height = image.height;
  const context = canvas.getContext('2d', { willReadFrequently: true });
  context.drawImage(image, 0, 0);
  const { data } = context.getImageData(0, 0, image.width, image.height);
  const mask = new Uint8Array(image.width * image.height);
  for (let i = 0; i < mask.length; i++) mask[i] = data[i * 4];
  return { mask, width: image.width, height: image.height };
};

// Returns the blade roots in patch space, [-1, 1] on x and z (the vertex
// shader scales by the patch size), as a flat Float32Array of (x, z) pairs
const generatePlacement = ({ mask, width, height }, count) => {
  const random = mulberry32(SEED);
  const blades = [];

  // Rejection sampling: ~27% of the patch is grass, so about 4 tries per
  // blade. The cap only matters if the mask is (wrongly) empty.
  const maxTries = count * 64;
  for (let tries = 0; blades.length < count && tries < maxTries; tries++) {
    const u = random();
    const v = random();
    const column = Math.min(width - 1, (u * width) | 0);
    const row = Math.min(height - 1, (v * height) | 0);
    if (mask[row * width + column] < PLACEMENT_THRESHOLD) continue;
    blades.push({
      u,
      v,
      cell: ((v * SORT_GRID) | 0) * SORT_GRID + ((u * SORT_GRID) | 0),
    });
  }
  blades.sort((a, b) => a.cell - b.cell);

  const positions = new Float32Array(blades.length * 2);
  blades.forEach(({ u, v }, i) => {
    // The shader samples the height texture at s = 0.5 - x/2, t = 0.5 - z/2,
    // and t = 1 is the image's top row (three's flipY convention, which the
    // flipped KTX2 bake reproduces). So mask column u -> x = 1 - 2u and mask
    // row v (0 = top) -> z = 2v - 1. Verified against the island collider:
    // 92% of the placed blades sit on the flat plateau with this mapping.
    positions[i * 2] = 1 - 2 * u;
    positions[i * 2 + 1] = 2 * v - 1;
  });
  return positions;
};

const useGrassPlacement = count => {
  // Goes through the default loading manager like every other asset, so the
  // intro loader counts it
  const image = useLoader(THREE.ImageLoader, grassPlacementUrl);
  return useMemo(
    () => generatePlacement(readMask(image), count),
    [image, count]
  );
};

export { useGrassPlacement };
